import json
import math
from pathlib import Path


def _check_finite(value):
    if isinstance(value, float) and (math.isnan(value) or math.isinf(value)):
        raise ValueError("non-finite number")
    return value


def _validate(value):
    if isinstance(value, dict):
        return {k: _validate(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_validate(v) for v in value]
    if isinstance(value, float):
        return _check_finite(value)
    return value


def load_payload(path):
    path = Path(path)
    text = path.read_text(encoding="utf-8")
    try:
        data = json.loads(text, parse_constant=lambda s: (_ for _ in ()).throw(ValueError("non-finite number")))
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("invalid JSON") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    return _validate(data)

def transform(payloads, contract):
    if not isinstance(payloads, list) or not isinstance(contract, dict):
        raise ValueError("bad arguments")
    if "name" not in contract:
        raise ValueError("missing name")
    if "inputs" not in contract or not isinstance(contract["inputs"], list):
        raise ValueError("missing inputs")
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    payload = payloads[0]
    # If the object has exactly keys name/result, the business input is its result.
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        payload = payload["result"]

    if not isinstance(payload, dict):
        raise ValueError("payload must be object")

    objects = payload.get("objects")
    target = payload.get("target")
    if not isinstance(objects, list):
        raise ValueError("missing objects")
    if not isinstance(target, str):
        raise ValueError("missing target")

    by_id = {}
    for obj in objects:
        if not isinstance(obj, dict) or "id" not in obj:
            raise ValueError("bad object")
        by_id[obj["id"]] = obj

    if target not in by_id:
        raise ValueError("unknown target")

    # Candidate order: target then its mro.
    order = [target] + list(by_id[target].get("mro", []))
    provider = None
    for oid in order:
        obj = by_id.get(oid)
        if obj is None:
            raise ValueError("unknown mro id")
        doc = obj.get("doc")
        if isinstance(doc, str) and doc.strip():
            provider = oid
            break

    if provider is None:
        return {"name": contract["name"], "result": {"provider": None, "namespace": None, "aliases": {}}}

    pobj = by_id[provider]
    namespace = pobj.get("namespace")
    aliases = pobj.get("aliases")
    if not isinstance(aliases, dict):
        aliases = {}

    return {
        "name": contract["name"],
        "result": {
            "provider": provider,
            "namespace": namespace,
            "aliases": aliases,
        },
    }

import ast


def _unparse(node):
    return ast.unparse(node)


def _parse_signature(sig):
    # Wrap as a function definition to reuse Python's parser.
    src = "def " + sig + ":\n    pass\n"
    tree = ast.parse(src)
    func = tree.body[0]
    args = func.args
    params = []

    # positional-only
    for a in args.posonlyargs:
        params.append({
            "name": a.arg,
            "kind": "posonly",
            "annotation": _unparse(a.annotation) if a.annotation is not None else None,
            "default": _unparse(args.defaults[len(args.defaults) - len(args.posonlyargs) + args.posonlyargs.index(a)]) if args.posonlyargs.index(a) >= len(args.posonlyargs) - len(args.defaults) else None,
        })

    # positional-or-keyword
    n_pos = len(args.args)
    n_defaults = len(args.defaults)
    for i, a in enumerate(args.args):
        has_default = i >= n_pos - n_defaults
        params.append({
            "name": a.arg,
            "kind": "positional",
            "annotation": _unparse(a.annotation) if a.annotation is not None else None,
            "default": _unparse(args.defaults[i - (n_pos - n_defaults)]) if has_default else None,
        })

    if args.vararg is not None:
        params.append({
            "name": args.vararg.arg,
            "kind": "vararg",
            "annotation": _unparse(args.vararg.annotation) if args.vararg.annotation is not None else None,
            "default": None,
        })

    # keyword-only
    for i, a in enumerate(args.kwonlyargs):
        has_default = i >= len(args.kwonlyargs) - len(args.kw_defaults)
        params.append({
            "name": a.arg,
            "kind": "kwonly",
