_IDENT = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _balanced_parens(s):
    depth = 0
    for ch in s:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth < 0:
                return False
