    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        payload = payload["result"]
    objects = payload["objects"]
    docs = {}
    for obj in objects:
        oid = obj["id"]
        doc = obj["doc"]
        entries = _parse_doc(doc)
        # build map
        params = {}  # name -> {type, description}
        for name, type_part, desc in entries:
