        provider_docs = docs.get(provider, [])
        parameters = []
        for entry in provider_docs:
            parameters.append(
                {
                    "name": entry["name"],
                    "type": _qualify_type(entry["type"], aliases),
                    "description": entry["description"],
                }
            )

    return {
        "name": contract["name"],
        "result": {
            "overloads": overloads,
            "provider": provider,
            "namespace": namespace,
            "parameters": parameters,
        },
    }
